<?php require_once __DIR__.'/../config/security.php'; require_permission('backup.manage'); $d=json_decode(file_get_contents('php://input'),true)?:$_POST; if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($d['name'])){$pdo->prepare('INSERT INTO report_schedules(name,recipient_email,frequency,enabled) VALUES(?,?,?,1)')->execute([$d['name'],$d['recipient_email'],$d['frequency']??'daily']);audit('Created report schedule',$d['recipient_email']);json_response(['ok'=>true]);} $subject=$d['subject']??'Campus Network Alert';$body=$d['body']??'';$to=$d['to']??'';if(!$to)json_response(['ok'=>false,'message'=>'Recipient required'],422);$headers='From: '.setting('smtp_from','no-reply@campus.local');$ok=@mail($to,$subject,$body,$headers);$pdo->prepare('INSERT INTO notification_queue(recipient_email,subject,body,status,attempts,sent_at) VALUES(?,?,?,?,?,?)')->execute([$to,$subject,$body,$ok?'Sent':'Failed',1,$ok?date('Y-m-d H:i:s'):null]);json_response(['ok'=>$ok,'message'=>$ok?'Email sent/queued by PHP mail.':'PHP mail() could not send. Configure a mail transport/SMTP relay.']);}json_response(['ok'=>false],405);
